/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'fs'

// ============================================================================
// Constants and utilities
// ============================================================================

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const KEYWORDS = new Set(['TRUE', 'FALSE'])
const FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

// ============================================================================
// Address parsing and validation
// ============================================================================

function parseAddress(addr) {
  const match = addr.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) return null
  const col = match[1]
  const row = parseInt(match[2], 10)
  if (row < 1 || row > 999) return null
  return { col, row, str: col + row }
}

function addressToString(addr) {
  return addr.col + addr.row
}

function addressKey(addr) {
  return `${addr.col}:${addr.row}`
}

function normalizeAddress(str) {
  return str.toUpperCase()
}

// ============================================================================
// Lexer for formulas
// ============================================================================

function tokenize(formula) {
  const tokens = []
  let i = 0
  while (i < formula.length) {
    const ch = formula[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LPAREN', value: '(' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RPAREN', value: ')' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON', value: ':' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA', value: ',' })
      i++
      continue
    }
    if (ch === '^') {
      tokens.push({ type: 'POW', value: '^' })
      i++
      continue
    }
    if (ch === '*') {
      tokens.push({ type: 'MUL', value: '*' })
      i++
      continue
    }
    if (ch === '/') {
      tokens.push({ type: 'DIV', value: '/' })
      i++
      continue
    }
    if (ch === '+') {
      tokens.push({ type: 'PLUS', value: '+' })
      i++
      continue
    }
    if (ch === '-') {
      tokens.push({ type: 'MINUS', value: '-' })
      i++
      continue
    }
    if (ch === '=') {
      if (i + 1 < formula.length && formula[i + 1] === '<') {
        tokens.push({ type: 'LE', value: '<=' })
        i += 2
        continue
      }
      tokens.push({ type: 'EQ', value: '=' })
      i++
      continue
    }
    if (ch === '<') {
      if (i + 1 < formula.length && formula[i + 1] === '>') {
        tokens.push({ type: 'NE', value: '<>' })
        i += 2
        continue
      }
      if (i + 1 < formula.length && formula[i + 1] === '=') {
        tokens.push({ type: 'LT', value: '<=' })
        i += 2
        continue
      }
      tokens.push({ type: 'LT', value: '<' })
      i++
      continue
    }
    if (ch === '>') {
      if (i + 1 < formula.length && formula[i + 1] === '=') {
        tokens.push({ type: 'GE', value: '>=' })
        i += 2
        continue
      }
      tokens.push({ type: 'GT', value: '>' })
      i++
      continue
    }
    // Number
    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < formula.length && (formula[j] >= '0' && formula[j] <= '9')) j++
      if (j < formula.length && formula[j] === '.') {
        j++
        while (j < formula.length && (formula[j] >= '0' && formula[j] <= '9')) j++
      }
      tokens.push({ type: 'NUMBER', value: parseFloat(formula.slice(i, j)) })
      i = j
      continue
    }
    // Word (identifier, cell address, keyword)
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
      let j = i
      while (j < formula.length && ((formula[j] >= 'A' && formula[j] <= 'Z') ||
                                     (formula[j] >= 'a' && formula[j] <= 'z') ||
                                     (formula[j] >= '0' && formula[j] <= '9'))) {
        j++
      }
      const word = formula.slice(i, j).toUpperCase()
      tokens.push({ type: 'WORD', value: word })
      i = j
      continue
    }
    return null // Invalid character
  }
  return tokens
}

// ============================================================================
// Parser
// ============================================================================

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null
  }

  consume() {
    return this.tokens[this.pos++]
  }

  expectType(type) {
    const token = this.peek()
    if (!token || token.type !== type) return null
    return this.consume()
  }

  parse() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (left === null) return null

    while (true) {
      const token = this.peek()
      if (!token || !['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'].includes(token.type)) break
      const op = this.consume()
      const right = this.parseAdditive()
      if (right === null) return null
      left = { type: 'BINOP', op: op.value, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (left === null) return null

    while (true) {
      const token = this.peek()
      if (!token || !['PLUS', 'MINUS'].includes(token.type)) break
      const op = this.consume()
      const right = this.parseMultiplicative()
      if (right === null) return null
      left = { type: 'BINOP', op: op.value, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    if (left === null) return null

    while (true) {
      const token = this.peek()
      if (!token || !['MUL', 'DIV'].includes(token.type)) break
      const op = this.consume()
      const right = this.parsePower()
      if (right === null) return null
      left = { type: 'BINOP', op: op.value, left, right }
    }
    return left
  }

  parsePower() {
    let left = this.parseUnary()
    if (left === null) return null

    if (this.peek() && this.peek().type === 'POW') {
      const op = this.consume()
      const right = this.parsePower() // Right associative
      if (right === null) return null
      left = { type: 'BINOP', op: op.value, left, right }
    }
    return left
  }

  parseUnary() {
    const token = this.peek()
    if (token && ['PLUS', 'MINUS'].includes(token.type)) {
      const op = this.consume()
      const expr = this.parseUnary()
      if (expr === null) return null
      return { type: 'UNOP', op: op.value, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.peek()
    if (!token) return null

    if (token.type === 'NUMBER') {
      this.consume()
      return { type: 'NUMBER', value: token.value }
    }

    if (token.type === 'LPAREN') {
      this.consume()
      const expr = this.parseComparison()
      if (expr === null || !this.expectType('RPAREN')) return null
      return expr
    }

    if (token.type === 'WORD') {
      const word = token.value
      this.consume()

      if (word === 'TRUE') {
        return { type: 'BOOL', value: true }
      }
      if (word === 'FALSE') {
        return { type: 'BOOL', value: false }
      }

      // Check if it's a function call
      if (this.peek() && this.peek().type === 'LPAREN') {
        if (!FUNCTIONS.has(word)) {
          return { type: 'FUNCALL', name: word, args: null } // Invalid function
        }
        this.consume() // consume LPAREN
        const args = this.parseArguments()
        if (args === null || !this.expectType('RPAREN')) return null
        return { type: 'FUNCALL', name: word, args }
      }

      // Check if it's a cell address
      const parsed = parseAddress(word)
      if (parsed) {
        // Check if it's a range
        if (this.peek() && this.peek().type === 'COLON') {
          this.consume()
          const token2 = this.peek()
          if (!token2 || token2.type !== 'WORD') return null
          const end = token2.value
          this.consume()
          const parsedEnd = parseAddress(end)
          if (!parsedEnd) return null
          return { type: 'RANGE', start: parsed, end: parsedEnd }
        }
        return { type: 'CELL', addr: parsed }
      }

      // Unknown word that's not an address
      return { type: 'CELL', addr: null } // Will be #REF!
    }

    return null
  }

  parseArguments() {
    const args = []

    if (this.peek() && this.peek().type === 'RPAREN') {
      return args // Empty argument list
    }

    while (true) {
      const arg = this.parseComparison()
      if (arg === null) return null
      args.push(arg)

      const token = this.peek()
      if (!token) return null
      if (token.type === 'RPAREN') {
        break
      }
      if (token.type === 'COMMA') {
        this.consume()
        continue
      }
      return null
    }

    return args
  }
}

function parseFormula(formula) {
  if (!formula.startsWith('=')) return null
  const tokens = tokenize(formula.slice(1))
  if (tokens === null) return null
  const parser = new Parser(tokens)
  const ast = parser.parse()
  if (ast === null || parser.pos !== parser.tokens.length) return null
  return ast
}

// ============================================================================
// Evaluator
// ============================================================================

class Evaluator {
  constructor(cells) {
    this.cells = cells // Map of address key to { content, ast, value, deps, evaluated }
    this.evaluating = new Set()
  }

  evaluate(addrKey) {
    const cell = this.cells.get(addrKey)
    if (!cell) {
      return { value: 0, deps: new Set() }
    }

    if (cell.evaluated) {
      return { value: cell.value, deps: cell.deps }
    }

    if (this.evaluating.has(addrKey)) {
      return { value: '#CYCLE!', deps: new Set() }
    }

    this.evaluating.add(addrKey)

    let value
    let deps = new Set()

    // Parse content
    const content = cell.content
    if (content.startsWith('=')) {
      // Formula
      const ast = parseFormula(content)
      if (ast === null) {
        value = '#ERR!'
      } else {
        const result = this.evaluateAst(ast)
        value = result.value
        deps = result.deps
      }
    } else {
      // Literal
      value = this.parseLiteral(content)
    }

    // Handle cycle detection
    if (value === '#CYCLE!') {
      this.evaluating.delete(addrKey)
      cell.evaluated = true
      cell.value = value
      cell.deps = deps
      return { value, deps }
    }

    this.evaluating.delete(addrKey)
    cell.evaluated = true
    cell.value = value
    cell.deps = deps
    return { value, deps }
  }

  evaluateAst(ast) {
    if (ast.type === 'NUMBER') {
      return { value: ast.value, deps: new Set() }
    }
    if (ast.type === 'BOOL') {
      return { value: ast.value, deps: new Set() }
    }
    if (ast.type === 'CELL') {
      if (ast.addr === null) {
        return { value: '#REF!', deps: new Set() }
      }
      const addrKey = addressKey(ast.addr)
      const result = this.evaluate(addrKey)
      result.deps.add(addrKey)
      return result
    }
    if (ast.type === 'RANGE') {
      // Ranges should not appear outside function arguments
      return { value: '#ERR!', deps: new Set() }
    }
    if (ast.type === 'UNOP') {
      const expr = this.evaluateAst(ast.expr)
      if (expr.value === '#CYCLE!') return expr
      if (this.isError(expr.value)) return expr
      const num = this.toNumber(expr.value)
      if (this.isError(num)) return { value: num, deps: expr.deps }
      const result = ast.op === '-' ? -num : num
      return { value: result, deps: expr.deps }
    }
    if (ast.type === 'BINOP') {
      const left = this.evaluateAst(ast.left)
      if (left.value === '#CYCLE!') return left
      const right = this.evaluateAst(ast.right)
      if (right.value === '#CYCLE!') return right

      if (this.isError(left.value)) {
        return { value: left.value, deps: new Set([...left.deps, ...right.deps]) }
      }
      if (this.isError(right.value)) {
        return { value: right.value, deps: new Set([...left.deps, ...right.deps]) }
      }

      const deps = new Set([...left.deps, ...right.deps])

      if (['=', '<>', '<', '<=', '>', '>='].includes(ast.op)) {
        const result = this.compare(ast.op, left.value, right.value)
        return { value: result, deps }
      } else {
        const leftNum = this.toNumber(left.value)
        if (this.isError(leftNum)) return { value: leftNum, deps }
        const rightNum = this.toNumber(right.value)
        if (this.isError(rightNum)) return { value: rightNum, deps }

        let result
        if (ast.op === '+') {
          result = leftNum + rightNum
        } else if (ast.op === '-') {
          result = leftNum - rightNum
        } else if (ast.op === '*') {
          result = leftNum * rightNum
        } else if (ast.op === '/') {
          if (rightNum === 0) {
            return { value: '#DIV/0!', deps }
          }
          result = leftNum / rightNum
        } else if (ast.op === '^') {
          result = Math.pow(leftNum, rightNum)
        }

        if (!isFinite(result)) {
          return { value: '#DIV/0!', deps }
        }
        return { value: result, deps }
      }
    }
    if (ast.type === 'FUNCALL') {
      if (ast.args === null || !FUNCTIONS.has(ast.name)) {
        return { value: '#NAME?', deps: new Set() }
      }

      const func = ast.name
      const args = ast.args

      // Validate argument count
      if (func === 'ABS' && args.length !== 1) {
        return { value: '#ERR!', deps: new Set() }
      }
      if (func === 'IF' && args.length !== 3) {
        return { value: '#ERR!', deps: new Set() }
      }
      if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(func) && args.length === 0) {
        return { value: '#ERR!', deps: new Set() }
      }

      // Special handling for IF
      if (func === 'IF') {
        const cond = this.evaluateAst(args[0])
        if (cond.value === '#CYCLE!') return cond
        if (this.isError(cond.value)) {
          return { value: cond.value, deps: cond.deps }
        }
        const condBool = this.isTrue(cond.value)
        if (condBool) {
          const thenVal = this.evaluateAst(args[1])
          return { value: thenVal.value, deps: new Set([...cond.deps, ...thenVal.deps]) }
        } else {
          const elseVal = this.evaluateAst(args[2])
          return { value: elseVal.value, deps: new Set([...cond.deps, ...elseVal.deps]) }
        }
      }

      // Collect all values from arguments
      const values = []
      let deps = new Set()
      let hasError = null

      for (const arg of args) {
        if (arg.type === 'RANGE') {
          const cells = this.expandRange(arg.start, arg.end)
          for (const cell of cells) {
            const result = this.evaluate(cell)
            if (result.value === '#CYCLE!') return result
            deps = new Set([...deps, ...result.deps])
            if (this.isError(result.value)) {
              if (!hasError) hasError = result.value
            } else {
              values.push(result.value)
            }
          }
        } else {
          const result = this.evaluateAst(arg)
          if (result.value === '#CYCLE!') return result
          deps = new Set([...deps, ...result.deps])
          if (this.isError(result.value)) {
            if (!hasError) hasError = result.value
          } else {
            values.push(result.value)
          }
        }
      }

      if (hasError && func !== 'COUNT') {
        return { value: hasError, deps }
      }

      // Evaluate function
      if (func === 'SUM') {
        if (hasError) return { value: hasError, deps }
        const nums = values.map(v => this.toNumber(v))
        if (nums.some(n => this.isError(n))) {
          return { value: '#VALUE!', deps }
        }
        return { value: nums.reduce((a, b) => a + b, 0), deps }
      }
      if (func === 'MIN') {
        if (hasError) return { value: hasError, deps }
        const nums = values.map(v => this.toNumber(v))
        if (nums.some(n => this.isError(n))) {
          return { value: '#VALUE!', deps }
        }
        return { value: Math.min(...nums), deps }
      }
      if (func === 'MAX') {
        if (hasError) return { value: hasError, deps }
        const nums = values.map(v => this.toNumber(v))
        if (nums.some(n => this.isError(n))) {
          return { value: '#VALUE!', deps }
        }
        return { value: Math.max(...nums), deps }
      }
      if (func === 'AVG') {
        if (hasError) return { value: hasError, deps }
        const nums = values.map(v => this.toNumber(v))
        if (nums.some(n => this.isError(n))) {
          return { value: '#VALUE!', deps }
        }
        return { value: nums.reduce((a, b) => a + b, 0) / nums.length, deps }
      }
      if (func === 'COUNT') {
        let count = 0
        for (const v of values) {
          if (typeof v === 'number') count++
        }
        return { value: count, deps }
      }
      if (func === 'ABS') {
        if (hasError) return { value: hasError, deps }
        const num = this.toNumber(values[0])
        if (this.isError(num)) return { value: num, deps }
        return { value: Math.abs(num), deps }
      }
    }
    return { value: '#ERR!', deps: new Set() }
  }

  expandRange(start, end) {
    const cells = []
    const colStart = this.colIndex(start.col)
    const colEnd = this.colIndex(end.col)
    const rowStart = start.row
    const rowEnd = end.row

    const minCol = Math.min(colStart, colEnd)
    const maxCol = Math.max(colStart, colEnd)
    const minRow = Math.min(rowStart, rowEnd)
    const maxRow = Math.max(rowStart, rowEnd)

    for (let col = minCol; col <= maxCol; col++) {
      for (let row = minRow; row <= maxRow; row++) {
        const colStr = this.indexToCol(col)
        cells.push(addressKey({ col: colStr, row }))
      }
    }
    return cells
  }

  colIndex(col) {
    let index = 0
    for (let i = 0; i < col.length; i++) {
      index = index * 26 + (col.charCodeAt(i) - 65 + 1)
    }
    return index
  }

  indexToCol(index) {
    let col = ''
    while (index > 0) {
      index--
      col = String.fromCharCode(65 + (index % 26)) + col
      index = Math.floor(index / 26)
    }
    return col
  }

  parseLiteral(content) {
    if (content === '') return 0
    if (ERROR_TOKENS.has(content)) return content
    const num = parseFloat(content)
    if (!isNaN(num) && content.match(/^-?\d+(\.\d+)?$/)) {
      return num
    }
    return content
  }

  toNumber(value) {
    if (typeof value === 'number') return value
    if (typeof value === 'boolean') return value ? 1 : 0
    if (typeof value === 'string') return '#VALUE!'
    return value
  }

  isError(value) {
    return typeof value === 'string' && value.startsWith('#')
  }

  isTrue(value) {
    if (value === true) return true
    if (value === false) return false
    if (typeof value === 'number') return value !== 0
    return false
  }

  compare(op, left, right) {
    // Numbers vs numbers: numeric
    // Texts vs texts: code point
    // Booleans vs booleans: false < true
    // Mixed: numbers < texts < booleans

    const leftType = typeof left
    const rightType = typeof right

    let cmp
    if (leftType === 'number' && rightType === 'number') {
      cmp = left < right ? -1 : left > right ? 1 : 0
    } else if (leftType === 'string' && rightType === 'string') {
      cmp = left < right ? -1 : left > right ? 1 : 0
    } else if (leftType === 'boolean' && rightType === 'boolean') {
      cmp = left < right ? -1 : left > right ? 1 : 0
    } else {
      // Mixed types
      const leftOrder = this.typeOrder(left)
      const rightOrder = this.typeOrder(right)
      if (leftOrder !== rightOrder) {
        cmp = leftOrder < rightOrder ? -1 : 1
      } else {
        cmp = 0
      }
    }

    if (op === '=') return cmp === 0
    if (op === '<>') return cmp !== 0
    if (op === '<') return cmp < 0
    if (op === '<=') return cmp <= 0
    if (op === '>') return cmp > 0
    if (op === '>=') return cmp >= 0
  }

  typeOrder(value) {
    if (typeof value === 'number') return 0
    if (typeof value === 'string') return 1
    if (typeof value === 'boolean') return 2
    return 3
  }
}

// ============================================================================
// Main
// ============================================================================

function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['values', 'deps'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read stdin
  const input = readFileSync(0, 'utf8')
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  // Parse input
  const cells = new Map() // Map of address key to { content, value, deps, evaluated }
  const declared = new Set()

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    let line = lines[lineNum]

    // Strip leading spaces and tabs
    line = line.replace(/^[ \t]+/, '')

    // Skip empty lines and comments
    if (line === '' || line.startsWith('#')) {
      continue
    }

    // Parse address and content
    const match = line.match(/^([A-Za-z]+\d+)[ \t]+(.*)$/)
    if (!match) {
      process.stderr.write(`error: line ${lineNum + 1}: invalid cell address\n`)
      process.exit(2)
    }

    const addrStr = normalizeAddress(match[1])
    const content = match[2]

    const addr = parseAddress(addrStr)
    if (!addr) {
      process.stderr.write(`error: line ${lineNum + 1}: invalid cell address ${addrStr}\n`)
      process.exit(2)
    }

    const key = addressKey(addr)
