{"file_path":"src/sheet.js","content":"/** Reading the sheet: one cell per line, `<address><space><content>`. */

import { parseAddress, canonical } from './address.js'

/**
 * Split the input into declarations. Returns { cells } or { error } holding the
 * message of the first failure.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = []
  const seen = new Set()

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++
    const word = line.slice(0, end).toUpperCase()
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) rest++
    const content = line.slice(rest)

    const addr = parseAddress(word)
    if (!addr) {
      return { error: `line ${lineNumber}: invalid cell address ${word}` }
    }
    const address = canonical(addr)
    if (seen.has(address)) {
      return { error: `line ${lineNumber}: cell ${address} is declared twice` }
    }
    seen.add(address)
    cells.push({ address, content })
  }

  return { cells }
}
"}

