{"file_path":"src/deps.js","content":"/**
 * The cells a cell's content names directly, ranges expanded. A literal names
 * none, and so does a formula the grammar does not accept; only addresses
 * inside the addressable range are named.
 */

import { canonical, expandRange } from './address.js'

export function directDeps(node) {
  const out = new Set()
  walk(node, out)
  return out
}

function walk(node, out) {
  switch (node.k) {
    case 'ref':
      if (node.addr) out.add(canonical(node.addr))
      return
    case 'range':
      if (node.start && node.end) for (const a of expandRange(node.start, node.end)) out.add(a)
      return
    case 'unary':
      walk(node.e, out)
      return
    case 'binary':
      walk(node.l, out)
      walk(node.r, out)
      return
    case 'call':
      for (const arg of node.args) walk(arg, out)
      return
    default:
      return
  }
}
"}

