{"file_path":"src/evaluate.js","content":"/**
 * Evaluating cells. A value is { t: 'num' | 'text' | 'bool' | 'err', v }.
 */

import { canonical, expandRange } from './address.js'

const num = (v) => ({ t: 'num', v })
const text = (v) => ({ t: 'text', v })
const bool = (v) => ({ t: 'bool', v })
const err = (v) => ({ t: 'err', v })

const ZERO = num(0)
const DIV0 = err('#DIV/0!')
const REF = err('#REF!')
const VALUE = err('#VALUE!')
const CYCLE = err('#CYCLE!')
const NAME = err('#NAME?')
const ERR = err('#ERR!')

const ARITY = {
  SUM: [1, Infinity],
  MIN: [1, Infinity],
  MAX: [1, Infinity],
  COUNT: [1, Infinity],
  AVG: [1, Infinity],
  ABS: [1, 1],
  IF: [3, 3],
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.active = new Set()
  }

  /** The value of the cell at a canonical address. */
  evaluateCell(address) {
    if (this.cache.has(address)) return this.cache.get(address)
    const cell = this.cells.get(address)
    if (cell === undefined) return ZERO
    if (this.active.has(address)) return CYCLE
    this.active.add(address)
    let value
    if (cell.node.k === 'literal') value = cell.node.value
    else if (cell.node.k === 'invalid') value = ERR
    else value = this.evaluateNode(cell.node)
    this.active.delete(address)
    this.cache.set(address, value)
    return value
  }

  evaluateNode(node) {
    switch (node.k) {
      case 'num':
        return finite(node.v)
      case 'bool':
        return bool(node.v)
      case 'ref':
        return node.addr === null ? REF : this.evaluateCell(canonical(node.addr))
      case 'range':
        // A range is only allowed directly as a function argument.
        return ERR
      case 'unary': {
        const v = this.evaluateNode(node.e)
        if (v.t === 'err') return v
        const n = toNumber(v)
        if (n.t === 'err') return n
        return finite(node.op === '-' ? -n.v : n.v)
      }
      case 'binary':
        return this.evaluateBinary(node)
      case 'call':
        return this.evaluateCall(node)
      default:
        return ERR
    }
  }

  evaluateBinary(node) {
    const left = this.evaluateNode(node.l)
    if (left.t === 'err') return left
    const right = this.evaluateNode(node.r)
    if (right.t === 'err') return right

    if (node.op === '=' || node.op === '<>' || node.op === '<' ||
        node.op === '<=' || node.op === '>' || node.op === '>=') {
      return bool(satisfies(node.op, compare(left, right)))
    }

    const a = toNumber(left)
    if (a.t === 'err') return a
    const b = toNumber(right)
    if (b.t === 'err') return b

    switch (node.op) {
      case '+':
        return finite(a.v + b.v)
      case '-':
        return finite(a.v - b.v)
      case '*':
        return finite(a.v * b.v)
      case '/':
        if (b.v === 0) return DIV0
        return finite(a.v / b.v)
      case '^':
        return finite(Math.pow(a.v, b.v))
      default:
        return ERR
    }
  }

  /** The values an argument contributes, ranges expanded. */
  argumentValues(arg) {
    if (arg.k === 'range') {
      if (arg.start === null || arg.end === null) return [REF]
      return expandRange(arg.start, arg.end).map((address) => this.evaluateCell(address))
    }
    return [this.evaluateNode(arg)]
  }

  evaluateCall(node) {
    const arity = ARITY[node.name]
    if (arity === undefined) return NAME
    if (node.args.length < arity[0] || node.args.length > arity[1]) return ERR

    if (node.name === 'IF') {
      const condition = this.argumentValues(node.args[0])
      const bad = condition.find((v) => v.t === 'err')
      if (bad) return bad
      const c = condition[0]
      if (c.t === 'text') return VALUE
      const taken = (c.t === 'bool' ? c.v : c.v !== 0) ? node.args[1] : node.args[2]
      const branch = this.argumentValues(taken)
      const bruised = branch.find((v) => v.t === 'err')
      if (bruised) return bruised
      return branch[0]
    }

    const values = []
    for (const arg of node.args) {
      for (const value of this.argumentValues(arg)) {
        if (value.t === 'err') return value
        values.push(value)
      }
    }

    if (node.name === 'COUNT') return num(values.filter((v) => v.t === 'num').length)

    const numbers = []
    for (const value of values) {
      const n = toNumber(value)
      if (n.t === 'err') return n
      numbers.push(n.v)
    }

    switch (node.name) {
      case 'SUM':
        return finite(numbers.reduce((a, b) => a + b, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((a, b) => a + b, 0) / numbers.length)
      case 'ABS':
        return finite(Math.abs(numbers[0]))
      default:
        return ERR
    }
  }
}

/** Any arithmetic result that is not finite is the division error. */
function finite(x) {
  return Number.isFinite(x) ? num(x) : DIV0
}

/** In an arithmetic position a boolean is 1 or 0 and text is the value error. */
function toNumber(value) {
  if (value.t === 'num') return value
  if (value.t === 'bool') return num(value.v ? 1 : 0)
  if (value.t === 'text') return VALUE
  return value
}

function kindOrder(value) {
  if (value.t === 'num') return 0
  if (value.t === 'text') return 1
  return 2
}

function compare(left, right) {
  const a = kindOrder(left)
  const b = kindOrder(right)
  if (a !== b) return a < b ? -1 : 1
  if (a === 0) return left.v < right.v ? -1 : left.v > right.v ? 1 : 0
  if (a === 1) return compareText(left.v, right.v)
  const x = left.v ? 1 : 0
  const y = right.v ? 1 : 0
  return x < y ? -1 : x > y ? 1 : 0
}

/** Two texts compare by code point. */
function compareText(a, b) {
  const x = [...a]
  const y = [...b]
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const ca = x[i].codePointAt(0)
    const cb = y[i].codePointAt(0)
    if (ca !== cb) return ca < cb ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

function satisfies(op, cmp) {
  switch (op) {
    case '=':
      return cmp === 0
    case '<>':
      return cmp !== 0
    case '<':
      return cmp < 0
    case '<=':
      return cmp <= 0
    case '>':
      return cmp > 0
    default:
      return cmp >= 0
  }
}

/** How a value prints. */
export function formatValue(value) {
  switch (value.t) {
    case 'num':
      return formatNumber(value.v)
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    default:
      return value.v
  }
}

function formatNumber(x) {
  if (!Number.isFinite(x)) return String(x)
  if (x === 0) return '0'
  return String(Number(x.toPrecision(10)))
}

export { num, text, bool, err }
"}

