    if (value === '#CYCLE!') {
      this.evaluating.delete(addrKey)
      cell.evaluated = true
      cell.value = value
      cell.deps = deps
      return { value, deps }
    }

    this.evaluating.delete(addrKey)
    cell.evaluated = true
    cell.value = value
    cell.deps = deps
    return { value, deps }
  }

