    if (ast.type === 'UNOP') {
      const expr = this.evaluateAst(ast.expr)
      if (expr.value === '#CYCLE!') return expr
      if (this.isError(expr.value)) return expr
      const num = this.toNumber(expr.value)
      if (this.isError(num)) return { value: num, deps: expr.deps }
