import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseContent } from './formula.js'
import { directDeps } from './deps.js'
import { Evaluator, formatValue } from './evaluate.js'
import { colIndex } from './address.js'

function usage() {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exitCode = 2
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    usage()
    return
  }
  const mode = argv[0]

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  const parsed = parseSheet(input)
  if (parsed.error) {
    process.stderr.write(`error: ${parsed.error}\n`)
    process.exitCode = 2
    return
  }

  // cells: Map canonical address -> { content, node }
  const cells = new Map()
  for (const decl of parsed.cells) {
    cells.set(decl.address, { content: decl.content, node: parseContent(decl.content) })
  }

  const order = [...cells.keys()].sort(compareAddresses)
  const out = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const address of order) {
      out.push(`${address}=${formatValue(evaluator.evaluateCell(address))}\n`)
    }
  } else {
    for (const address of order) {
      const deps = [...directDeps(cells.get(address).node)].sort(compareAddresses)
      out.push(deps.length ? `${address}: ${deps.join(' ')}\n` : `${address}:\n`)
    }
  }

  process.stdout.write(out.join(''))
}

function splitAddress(address) {
  const match = /^([A-Z]{1,2})([0-9]+)$/.exec(address)
  return { col: colIndex(match[1]), row: Number(match[2]) }
}

function compareAddresses(a, b) {
  const x = splitAddress(a)
  const y = splitAddress(b)
  if (x.col !== y.col) return x.col - y.col
  return x.row - y.row
}

