{"file_path":"src/sheet.js","content":"/** Reading the sheet: one cell per line, `<address><space><content>`. */

import { parseAddress, canonical } from './address.js'

/**
 * Split the input into declarations. Returns { cells } or { error } holding the
 * message of the first failure.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = []
  const seen = new Set()

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++
    const word = line.slice(0, end).toUpperCase()
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) rest++
    const content = line.slice(rest)

    const addr = parseAddress(word)
    if (!addr) {
      return { error: `line ${lineNumber}: invalid cell address ${word}` }
    }
    const address = canonical(addr)
    if (seen.has(address)) {
      return { error: `line ${lineNumber}: cell ${address} is declared twice` }
    }
    seen.add(address)
    cells.push({ address, content })
  }

  return { cells }
}
"}

{"file_path":"src/formula.js","content":"/**
 * Cell content: a literal, or a formula lexed and parsed into a tree.
 *
 * Nodes are
 *   { k: 'num', v }            a number
 *   { k: 'bool', v }           TRUE or FALSE
 *   { k: 'ref', addr }         a cell address, null when outside the range
 *   { k: 'range', start, end } a range, either end null when outside the range
 *   { k: 'call', name, args }
 *   { k: 'unary', op, e }
 *   { k: 'binary', op, l, r }
 *
 * A literal is { k: 'literal', value } and a formula the grammar rejects is
 * { k: 'invalid' }.
 */

import { parseAddress } from './address.js'

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

/** Parse the content of a cell. */
export function parseContent(content) {
  if (content.startsWith('=')) {
    const tokens = lex(content.slice(1))
    if (tokens === null) return { k: 'invalid' }
    const parser = new Parser(tokens)
    const node = parser.parseExpression()
    if (node === null || parser.pos !== tokens.length) return { k: 'invalid' }
    return node
  }
  return { k: 'literal', value: literalValue(content) }
}

/** The value of a literal: a number, an error, or text. */
function literalValue(content) {
  if (content === '') return { t: 'num', v: 0 }
  if (ERROR_TOKENS.has(content)) return { t: 'err', v: content }
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return { t: 'num', v: Number(content) }
  return { t: 'text', v: content }
}

const isDigit = (c) => c >= '0' && c <= '9'
const isLetter = (c) => (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')

/** Lex a formula body, or null when it holds something the grammar rejects. */
function lex(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const c = body[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (isDigit(c)) {
      let j = i
      while (j < body.length && isDigit(body[j])) j++
      if (j < body.length && body[j] === '.' && j + 1 < body.length && isDigit(body[j + 1])) {
        j++
        while (j < body.length && isDigit(body[j])) j++
      }
      tokens.push({ type: 'num', text: body.slice(i, j) })
      i = j
      continue
    }
    if (isLetter(c)) {
      let j = i
      while (j < body.length && (isLetter(body[j]) || isDigit(body[j]))) j++
      tokens.push({ type: 'word', text: body.slice(i, j).toUpperCase() })
      i = j
      continue
    }
    const two = body.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'op', text: two })
      i += 2
      continue
    }
    if ('^*/+-=<>'.includes(c)) {
      tokens.push({ type: 'op', text: c })
      i++
      continue
    }
    if (c === '(' || c === ')' || c === ',' || c === ':') {
      tokens.push({ type: c, text: c })
      i++
      continue
    }
    return null
  }
  return tokens
}

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>=']

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null
  }

  isOp(list) {
    const token = this.peek()
    return token !== null && token.type === 'op' && list.includes(token.text)
  }

  take(type) {
    const token = this.peek()
    if (token === null || token.type !== type) return null
    this.pos++
    return token
  }

  parseExpression() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (left === null) return null
    while (this.isOp(COMPARISONS)) {
      const op = this.tokens[this.pos++].text
      const right = this.parseAdditive()
      if (right === null) return null
      left = { k: 'binary', op, l: left, r: right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (left === null) return null
    while (this.isOp(['+', '-'])) {
      const op = this.tokens[this.pos++].text
      const right = this.parseMultiplicative()
      if (right === null) return null
      left = { k: 'binary', op, l: left, r: right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    if (left === null) return null
    while (this.isOp(['*', '/'])) {
      const op = this.tokens[this.pos++].text
      const right = this.parsePower()
      if (right === null) return null
      left = { k: 'binary', op, l: left, r: right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (left === null) return null
    if (this.isOp(['^'])) {
      this.pos++
      const right = this.parsePower()
      if (right === null) return null
      return { k: 'binary', op: '^', l: left, r: right }
    }
    return left
  }

  parseUnary() {
    if (this.isOp(['+', '-'])) {
      const op = this.tokens[this.pos++].text
      const e = this.parseUnary()
      if (e === null) return null
      return { k: 'unary', op, e }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.peek()
    if (token === null) return null

    if (token.type === 'num') {
      this.pos++
      return { k: 'num', v: Number(token.text) }
    }

    if (token.type === '(') {
      this.pos++
      const e = this.parseExpression()
      if (e === null || this.take(')') === null) return null
      return e
    }

    if (token.type === 'word') {
      this.pos++
      const word = token.text
      if (word === 'TRUE') return { k: 'bool', v: true }
      if (word === 'FALSE') return { k: 'bool', v: false }
      if (this.peek() !== null && this.peek().type === '(') {
        this.pos++
        const args = this.parseArguments()
        if (args === null || this.take(')') === null) return null
        return { k: 'call', name: word, args }
      }
      if (this.peek() !== null && this.peek().type === ':') {
        this.pos++
        const other = this.take('word')
        if (other === null) return null
        return { k: 'range', start: parseAddress(word), end: parseAddress(other.text) }
      }
      return { k: 'ref', addr: parseAddress(word) }
    }

    return null
  }

  parseArguments() {
    const args = []
    if (this.peek() !== null && this.peek().type === ')') return args
    for (;;) {
      const arg = this.parseExpression()
      if (arg === null) return null
      args.push(arg)
      if (this.peek() !== null && this.peek().type === ',') {
        this.pos++
        continue
      }
      return args
    }
  }
}
"}

{"file_path":"src/deps.js","content":"/**
 * The cells a cell's content names directly, ranges expanded. A literal names
 * none, and so does a formula the grammar does not accept; only addresses
 * inside the addressable range are named.
 */

import { canonical, expandRange } from './address.js'

export function directDeps(node) {
  const out = new Set()
  walk(node, out)
  return out
}

function walk(node, out) {
  switch (node.k) {
    case 'ref':
      if (node.addr) out.add(canonical(node.addr))
      return
    case 'range':
      if (node.start && node.end) for (const a of expandRange(node.start, node.end)) out.add(a)
      return
    case 'unary':
      walk(node.e, out)
      return
    case 'binary':
      walk(node.l, out)
      walk(node.r, out)
      return
    case 'call':
      for (const arg of node.args) walk(arg, out)
      return
    default:
      return
  }
}
"}

{"file_path":"src/evaluate.js","content":"/**
 * Evaluating cells. A value is { t: 'num' | 'text' | 'bool' | 'err', v }.
 */

import { canonical, expandRange } from './address.js'

const num = (v) => ({ t: 'num', v })
const text = (v) => ({ t: 'text', v })
const bool = (v) => ({ t: 'bool', v })
const err = (v) => ({ t: 'err', v })

const ZERO = num(0)
const DIV0 = err('#DIV/0!')
const REF = err('#REF!')
const VALUE = err('#VALUE!')
const CYCLE = err('#CYCLE!')
const NAME = err('#NAME?')
const ERR = err('#ERR!')

const ARITY = {
  SUM: [1, Infinity],
  MIN: [1, Infinity],
  MAX: [1, Infinity],
  COUNT: [1, Infinity],
  AVG: [1, Infinity],
  ABS: [1, 1],
  IF: [3, 3],
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.active = new Set()
  }

  /** The value of the cell at a canonical address. */
  evaluateCell(address) {
    if (this.cache.has(address)) return this.cache.get(address)
    const cell = this.cells.get(address)
    if (cell === undefined) return ZERO
    if (this.active.has(address)) return CYCLE
    this.active.add(address)
    let value
    if (cell.node.k === 'literal') value = cell.node.value
    else if (cell.node.k === 'invalid') value = ERR
    else value = this.evaluateNode(cell.node)
    this.active.delete(address)
    this.cache.set(address, value)
    return value
  }

  evaluateNode(node) {
    switch (node.k) {
      case 'num':
        return finite(node.v)
      case 'bool':
        return bool(node.v)
      case 'ref':
        return node.addr === null ? REF : this.evaluateCell(canonical(node.addr))
      case 'range':
        // A range is only allowed directly as a function argument.
        return ERR
      case 'unary': {
        const v = this.evaluateNode(node.e)
        if (v.t === 'err') return v
        const n = toNumber(v)
        if (n.t === 'err') return n
        return finite(node.op === '-' ? -n.v : n.v)
      }
      case 'binary':
        return this.evaluateBinary(node)
      case 'call':
        return this.evaluateCall(node)
      default:
        return ERR
    }
  }

  evaluateBinary(node) {
    const left = this.evaluateNode(node.l)
    if (left.t === 'err') return left
    const right = this.evaluateNode(node.r)
    if (right.t === 'err') return right

    if (node.op === '=' || node.op === '<>' || node.op === '<' ||
        node.op === '<=' || node.op === '>' || node.op === '>=') {
      return bool(satisfies(node.op, compare(left, right)))
    }

    const a = toNumber(left)
    if (a.t === 'err') return a
    const b = toNumber(right)
    if (b.t === 'err') return b

    switch (node.op) {
      case '+':
        return finite(a.v + b.v)
      case '-':
        return finite(a.v - b.v)
      case '*':
        return finite(a.v * b.v)
      case '/':
        if (b.v === 0) return DIV0
        return finite(a.v / b.v)
      case '^':
        return finite(Math.pow(a.v, b.v))
      default:
        return ERR
    }
  }

  /** The values an argument contributes, ranges expanded. */
  argumentValues(arg) {
    if (arg.k === 'range') {
      if (arg.start === null || arg.end === null) return [REF]
      return expandRange(arg.start, arg.end).map((address) => this.evaluateCell(address))
    }
    return [this.evaluateNode(arg)]
  }

  evaluateCall(node) {
    const arity = ARITY[node.name]
    if (arity === undefined) return NAME
    if (node.args.length < arity[0] || node.args.length > arity[1]) return ERR

    if (node.name === 'IF') {
      const condition = this.argumentValues(node.args[0])
      const bad = condition.find((v) => v.t === 'err')
      if (bad) return bad
      const c = condition[0]
      if (c.t === 'text') return VALUE
      const taken = (c.t === 'bool' ? c.v : c.v !== 0) ? node.args[1] : node.args[2]
      const branch = this.argumentValues(taken)
      const bruised = branch.find((v) => v.t === 'err')
      if (bruised) return bruised
      return branch[0]
    }

    const values = []
    for (const arg of node.args) {
      for (const value of this.argumentValues(arg)) {
        if (value.t === 'err') return value
        values.push(value)
      }
    }

    if (node.name === 'COUNT') return num(values.filter((v) => v.t === 'num').length)

    const numbers = []
    for (const value of values) {
      const n = toNumber(value)
      if (n.t === 'err') return n
      numbers.push(n.v)
    }

    switch (node.name) {
      case 'SUM':
        return finite(numbers.reduce((a, b) => a + b, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((a, b) => a + b, 0) / numbers.length)
      case 'ABS':
        return finite(Math.abs(numbers[0]))
      default:
        return ERR
    }
  }
}

/** Any arithmetic result that is not finite is the division error. */
function finite(x) {
  return Number.isFinite(x) ? num(x) : DIV0
}

/** In an arithmetic position a boolean is 1 or 0 and text is the value error. */
function toNumber(value) {
  if (value.t === 'num') return value
  if (value.t === 'bool') return num(value.v ? 1 : 0)
  if (value.t === 'text') return VALUE
  return value
}

function kindOrder(value) {
  if (value.t === 'num') return 0
  if (value.t === 'text') return 1
  return 2
}

function compare(left, right) {
  const a = kindOrder(left)
  const b = kindOrder(right)
  if (a !== b) return a < b ? -1 : 1
  if (a === 0) return left.v < right.v ? -1 : left.v > right.v ? 1 : 0
  if (a === 1) return compareText(left.v, right.v)
  const x = left.v ? 1 : 0
  const y = right.v ? 1 : 0
  return x < y ? -1 : x > y ? 1 : 0
}

/** Two texts compare by code point. */
function compareText(a, b) {
  const x = [...a]
  const y = [...b]
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const ca = x[i].codePointAt(0)
    const cb = y[i].codePointAt(0)
    if (ca !== cb) return ca < cb ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

function satisfies(op, cmp) {
  switch (op) {
    case '=':
      return cmp === 0
    case '<>':
      return cmp !== 0
    case '<':
      return cmp < 0
    case '<=':
      return cmp <= 0
    case '>':
      return cmp > 0
    default:
      return cmp >= 0
  }
}

/** How a value prints. */
export function formatValue(value) {
  switch (value.t) {
    case 'num':
      return formatNumber(value.v)
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    default:
      return value.v
  }
}

function formatNumber(x) {
  if (!Number.isFinite(x)) return String(x)
  if (x === 0) return '0'
  return String(Number(x.toPrecision(10)))
}

export { num, text, bool, err }
